import os, re, json

# Load grids from session
def load():
    d = os.environ['RLM_SESSION_DIR']
    session_basename = os.path.basename(d)
    jsonl_path = os.path.join(d, '..', 'sessions', session_basename + '.jsonl')

    if not os.path.exists(jsonl_path):
        return {}

    with open(jsonl_path, 'r') as f:
        content = f.read()

    G = {}
    for line in content.split('\n'):
        if not line.strip():
            continue
        # Look for Demo pair X (WxH): and Test input (WxH): sections
        matches = re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', line)
        for m in matches:
            k, w, h = m[1], int(m[2]), int(m[3])
            end_pos = m.end() - 1  # -1 to get newline
            # Parse the grid (up to h rows)
            grid_rows = []
            start = 0
            while len(grid_rows) < h:
                rest = content[end_pos + start - 1:]
                matches2 = re.finditer(r'^((?:\d+ )+)$', rest[:1000])
                for mt in matches2:
                    if mt.group(1).strip():
                        row = [int(x) for x in mt.group(1).split() if x]
                        if row:
                            grid_rows.append(row)
                        start += 1
                        if start > 1000:
                            break
                else:
                    break
            if k not in G and len(grid_rows) == h and all(len(r) == w for r in grid_rows):
                G[k] = [grid_rows]

    # Simpler approach: parse all text for grids
    return G

G = load()
print("Loaded grids:", G.keys())
if G:
